"""Build the prospective protocol after metadata/image qualification, before outcomes."""
from contract import *
def main():
 q=json.loads((A/'logs/METADATA_QUALIFICATION.json').read_text());image=json.loads((A/'logs/IMAGE_QUALIFICATION.json').read_text())
 protocol={'dataset':'Wu et al. 2021 local six-patient Visium cohort, Zenodo 4739739','patients':SAMPLES,'calibration_patients':CAL,'evaluation_patients':EVAL,'split_rule':'Fixed paired split: 1142243F calibration /1160920F evaluation (independent lab TNBC); CID4465 calibration /CID44971 evaluation (local TNBC); CID4535 calibration /CID4290 evaluation (local ER). Declared before gene expression values or outcomes.','genes':q['genes'],'panel':'S2-50 exact original order, all 50 genes','secondary_panel':'S2-280 overlap documented; optional evaluation omitted prospectively','count_files':q['count_files'],'primary_encoder':ENC,'models':{'M0':'Frozen C4 primary D1 three-seed image ensemble in original C0 normalized log-count units','M1':'C5/C7 spatial interpolation: inverse-distance power2 with up to16 nearest observed anchors V1, unweighted mean16 V2','M2':'C8 T1 patient-weighted per-gene z-score; destination fit on calibration patients only; interpolate, then inverse-map to common C0 normalized log-count units','M3':'Exactly 0.2 calibrated image +0.8 M2; source moments from original NCBI783/NCBI785, destination from calibration patients; no fit of weights'},'harmonization_identifiability':'Affine transformation commutes with normalized linear interpolation. M1 and M2 must be identical within numerical tolerance in common units; neither scale-dependent native errors nor roundoff can establish harmonization benefit/stability. C8A benefit concerned image-based cross-platform calibration. Its benefit cannot be isolated by M2-M1 here. This is recorded before outcomes.','budgets':[.1,.2,.4],'random_seeds':list(range(10)),'sampling':['random','spatial_FPS'],'sampling_definition':'Exact C7/policy.py label-free nested permutation/FPS. Round floor(N*budget+.5), V2 denominator all eligible tissue locations before forbidden-region exclusion.','regimes':{'V1':'All unobserved tissue scored','V2':'Three compact forbidden40% regions centered at25/50/75% of PC1 spatial rank, exact frozen C7 geometry; anchors outside; score fixed forbidden locations. All other unobserved values excluded too.'},'distance_bins_um':[0,150,300,600,1200,2400,None],'preprocessing':{'counts':'Published filtered count matrices, provided in-tissue flag only; finite nonnegative integer counts; log1p and unchanged C0 training mean/SD; no external library-size, depth or area normalization','coordinates':'Barcode-joined pixel centers; fullres micrometers/pixel from least-squares lattice mapping and documented100um pitch; spot-diameter metadata is recorded but not used for scale because inconsistent with source lattice','images':image['input_contract'],'target_units':'Common C0 standardized log1p count units for every method; per-gene linear native T1 metrics may be supplementary, never mistaken for common-scale error gains'},'controls':{'patient':EVAL[0],'coverage':.2,'random_mask_seed':0,'V1_geometry':0,'V2_geometry':1,'permutation_seeds':[0,1,2],'NC1':'Permute expression vectors among observed locations','NC2':'Permute observed coordinate assignment keeping expression vectors fixed; algebraically related to NC1, not independent evidence','NC3':'Permute image predictions across all locations; no expression inputs'},'metrics':['per-gene Pearson','Spearman','MSE','MAE','patient mean/median each','fraction genes Pearson>0,.1,.2,.3; constant genes count as not passing; undefined correlations excluded only from correlation means/medians'],'aggregation':'Mean over seeds, then equal geometry mean within patient/budget/regime/strategy; patient is biological unit; median across patients headline, individual results mandatory. No spot-level p values. Primary20% V1 random;10/40% support; FPS/V2 separate.','pass_criteria':{'meaningful_sparse':'M2-M0 median gene Pearson>=.02 AND relative mean MSE reduction>=.02 AND MAE no worse','core_support':'At least2/3 evaluation patients meaningful at>=2/3 budgets; positive median Pearson and error gains at each budget; at least2/3 patients M2 Pearson40>10 and MSE40<10; distance assessed and all V2 reported','harmonization':'Cannot establish positive M2-M1 gain for affine invariant interpolation. Full PASS clause3 requires real gain/stability beyond numerical tolerance and cannot be satisfied by construction. Do not waive this condition after results.','status':'If core support but harmonization unidentifiable, overall MIXED_FRESH_EXTERNAL_VALIDATION with core and fusion conclusions separated; if heterogeneous sparse benefit, MIXED; if no meaningful benefit on at least2 patients at any budget, FAIL_FRESH_EXTERNAL_VALIDATION. Any integrity/leakage failure FAIL_TECHNICAL. Report patient/platform/image limitations explicitly.','fusion_secondary':'Report patient Pearson/MSE/MAE gains; success requires>=2/3 improve all3 metrics at>=2/3 budgets, <=25% patient/budget settings MSE harm>2%; not required for core support.','distance':'Compare patient error-bin curves, avoid extrapolation-horizon claim; lack of universal monotonicity disclosed, not tuned away.'},'C9C':'Not preselected; optional only if readily available after C9B frozen','parent_head':'cc655dd8f3f6291024fb50fa818d55767ff93ddf','source_urls':q['sources'],'image_qualification':image,'no_evaluation_labels_accessed':True}
 dump(OUT/'configs/protocol.json',protocol)
 rows=q['patients']
 for r in rows:r['image_resolution']=image['patients'][r['sample_id']]['resolution'];r['qualification_status']=image['status']
 pd.DataFrame(rows).to_csv(A/'C9A_EXTERNAL_DATASET_MANIFEST.csv',index=False);(OUT/'C9A_EXTERNAL_DATASET_MANIFEST.csv').write_bytes((A/'C9A_EXTERNAL_DATASET_MANIFEST.csv').read_bytes())
if __name__=='__main__':main()
